{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Benzoylpiperidine, a phenylpiperidine, freely passes the BBB within 1 min by PET, directly supporting CNS access for the query's piperidine-phenyl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "PRE-084, which retains the 1-phenylcyclohexane core, reached 773.6 ng/g brain at 5 min in mice, demonstrating rapid CNS distribution of this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Meptazinol, a basic phenyl/cyclohexane amine, equilibrated rapidly across the BBB with CSF levels 49-67% of plasma in monkeys, showing meaningful CNS exposure for this amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Trihexyphenidyl, a piperidine with phenyl and cyclohexyl substituents, penetrates the BBB easily by PET, closely matching the query's pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Norcyclizine, a lipophilic aryl-piperazine, had a brain AUC/plasma AUC >2 in rats, providing direct evidence that this aryl-amine class achieves meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[11C]ketamine showed relatively poor brain uptake in animals, but the record attributes this to rapid metabolism rather than an intrinsic BBB permeability deficit; because the query lacks the ketone and N-methyl groups and is not rapidly metabolized, this negative result transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is phencyclidine (PCP), a lipophilic tertiary amine with a 1-phenylcyclohexylpiperidine scaffold. Multiple structurally related piperidine/arylcyclohexyl CNS agents show direct brain/CSF penetration by PET, brain concentration, and CSF/plasma measurements, strongly supporting meaningful CNS access. The only apparent negative (ketamine) is explained by rapid metabolism and does not transfer to the query.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for the exact query molecule in the provided records; however, multiple close analogues provide direct CNS penetration evidence.",
    "No explicit efflux transporter or human data for the query in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

